begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir free_registration_fixture.inc
select is(public.get_public_free_rsvp('b6200000-0000-4000-8000-000000000001')->'availability'->>'remaining','3','canonical published fixture is available');
select is(pg_temp.register(1)->>'kind','confirmed','one transaction confirms');
select is((select count(*)::integer from public.tickets where organizer_id='b6100000-0000-4000-8000-000000000001'),2,'exact quantity individual tickets');
select is((select count(*)::integer from public.orders where organizer_id='b6100000-0000-4000-8000-000000000001'),0,'no paid order for free RSVP');
select is(pg_temp.register(1),public.server_resolve_free_registration('b6300000-0000-4000-8000-000000000001',encode(digest('proof:1','sha256'),'hex')),'same identity returns original receipt');
select is(pg_temp.register(1,1)->>'kind','conflict','changed quantity conflicts');
select is(pg_temp.register(1,2,1,'Different')->>'kind','conflict','changed name conflicts');
select is(pg_temp.register(1,2,1,'Pat Guest','new@example.invalid')->>'kind','conflict','changed email conflicts');
select is(pg_temp.register(1,2,1,'Pat Guest','pat@example.invalid',repeat('e',64))->>'kind','unavailable','wrong proof gives no receipt');
select is(pg_temp.register(2)->>'reason','full','capacity rejects whole group');
select is(pg_temp.register(2)->>'remaining','1','rejection records remaining at attempt');
select is(pg_temp.register(3,1)->>'kind','confirmed','same email new request intentionally succeeds');
select is(public.get_public_free_rsvp('b6200000-0000-4000-8000-000000000001')->'availability'->>'status','full','full availability');
select is((select count(*)::integer from public.free_registrations where organizer_id='b6100000-0000-4000-8000-000000000001'),2,'rejected receipt creates no registration');
select is(pg_temp.register(4,10,2)->>'kind','confirmed','null capacity allows max quantity');
select is(public.get_public_free_rsvp('b6200000-0000-4000-8000-000000000002')->'availability'->'remaining','null'::jsonb,'unlimited remaining is null');
select is(pg_temp.register(5,11,2)->>'reason','invalid_input','bad quantity durable rejection');
select is(pg_temp.register(6,1,99)->>'reason','unavailable','nonexistent event durable rejection');
select is(pg_temp.register(7,1,2,' Pat Guest')->>'reason','invalid_input','SQL rejects noncanonical name');
select is(pg_temp.register(8,1,2,'Pat Guest','PAT@example.invalid')->>'reason','invalid_input','SQL rejects noncanonical email');
select is(public.server_resolve_free_registration('b6300000-0000-4000-8000-000000000099',repeat('a',64))->>'kind','not_found','unknown attempt is unresolved absence');
select throws_ok($$select public.server_confirm_free_registration('b6300000-0000-4000-8000-000000000009','b6200000-0000-4000-8000-000000000002','Pat Guest','pat@example.invalid',2,repeat('9',64),'[]')$$,'P0001','FREE_MANIFEST_INVALID','bad manifest rolls back');
select is((select count(*)::integer from public.free_registration_requests where id='b6300000-0000-4000-8000-000000000009'),0,'infrastructure failure leaves no receipt');
select throws_ok($$update public.events set capacity=2 where id='b6200000-0000-4000-8000-000000000001'$$,'P0001','FREE_CAPACITY_BELOW_RESERVED','direct capacity reduction protected');
select throws_ok($$update public.events set admission_type='paid' where id='b6200000-0000-4000-8000-000000000001'$$,'P0001','FREE_REGISTRATION_EVENT_IMMUTABLE','direct free to paid conversion protected');
select throws_ok($$update public.free_registrations set name='Other Guest' where organizer_id='b6100000-0000-4000-8000-000000000001'$$,'P0001','FREE_SOURCE_IMMUTABLE','registrant identity immutable');
select throws_ok($$delete from public.tickets where registration_id is not null and organizer_id='b6100000-0000-4000-8000-000000000001'$$,'P0001','FREE_SOURCE_IMMUTABLE','free admissions undeletable');
select throws_ok($$update public.tickets set registration_id=null where registration_id is not null and organizer_id='b6100000-0000-4000-8000-000000000001'$$,'P0001','TICKET_IDENTITY_IMMUTABLE','source immutable');
select is(jsonb_array_length(public.server_lookup_free_ticket_collection(encode(digest('proof:1','sha256'),'hex'))->'tickets'),2,'private collection returns exact source');
select is(public.server_lookup_free_ticket_collection(repeat('e',64)),null::jsonb,'wrong collection proof unavailable');
set constraints all immediate;
select pass('all deferred source constraints pass at commit boundary');
select * from finish();
rollback;
